import { promises as fs } from "fs";
import path from "path";
import type { StorageProvider } from "./provider";

const root = () => path.resolve(process.env.STORAGE_DIR ?? "./storage");

// Keys are generated by the server, but we still refuse anything that escapes the storage root.
function resolveKey(key: string) {
  const full = path.resolve(root(), key);
  if (!full.startsWith(root() + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export class LocalStorage implements StorageProvider {
  async save(key: string, data: Buffer) {
    const file = resolveKey(key);
    await fs.mkdir(path.dirname(file), { recursive: true });
    await fs.writeFile(file, data);
  }
  read(key: string) { return fs.readFile(resolveKey(key)); }
  async delete(key: string) { await fs.rm(resolveKey(key), { force: true }); }
}
